import tifffile
import matplotlib.pyplot as plt

img = tifffile.imread("Data/learning_picture.tif") #读取图像

#基本信息
print(img.shape)
print(img.dtype)
print(img.min())                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
print(img.max())
print(img.mean())

#创建画布
fig,axes = plt.subplots(1,2,figsize = (12,5))

#图1
im = axes[0].imshow(img,cmap = "gray")
axes[0].set_title("origin gray image")
plt.colorbar(im)
axes[0].axis("off") #关闭坐标轴 刻度 边框

axes[1].hist(img.ravel(),bins = 128)
axes[1].set_title("Histogram")

plt.tight_layout() #自动调整子图距离

plt.show()